@import url("https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=Inter:wght@400;500;600;700&display=swap");
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.sl-app {
  --ink: #2F323B;
  --paper: #FEFEFE;
  --card: #FFFFFF;
  --line: #A7CDDE;
  --text: #2F323B;
  --muted: #585A61;
  --blue: #2972A9;
  --cyan: #2E9BCB;
  --soft: rgba(167, 205, 222, 0.14);
  display: flex;
  height: 100vh;
  background: var(--paper);
  color: var(--text);
  font-family: "Inter", sans-serif;
}

.sidebar {
  width: 250px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--ink);
  color: #FEFEFE;
}

.brand-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.brand-logo {
  width: 40px;
  height: 40px;
  display: block;
  object-fit: contain;
  border-radius: 11px;
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: "Playfair Display", serif;
  font-size: 15px;
  font-weight: 700;
}

.brand-tag {
  margin-top: 2px;
  font-size: 9px;
  color: var(--cyan);
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

.nav-menu {
  flex: 1;
  overflow-y: auto;
  list-style: none;
  padding: 12px;
}

.nav-group {
  margin-bottom: 6px;
}

.nav-section-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px 6px;
  color: rgba(255, 255, 255, 0.35);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
}

.nav-section-head::after {
  content: "";
  width: 7px;
  height: 7px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
}

.nav-group.collapsed .nav-section-head::after {
  transform: rotate(-45deg);
}

.nav-group-items {
  list-style: none;
}

.nav-group.collapsed .nav-group-items {
  display: none;
}

.nav-item {
  position: relative;
  margin-bottom: 3px;
  padding: 10px 14px;
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.nav-item:hover {
  color: #FFFFFF;
  background: rgba(46, 155, 203, 0.1);
}

.nav-item.active {
  color: var(--cyan);
  background: linear-gradient(90deg, rgba(46, 155, 203, 0.2), transparent);
}

.nav-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 22%;
  width: 3px;
  height: 56%;
  border-radius: 3px;
  background: var(--cyan);
}

.sidebar-footer {
  padding: 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.logout-btn {
  width: 100%;
  padding: 10px;
  border: 1px solid rgba(167, 205, 222, 0.22);
  border-radius: 8px;
  background: transparent;
  color: rgba(255, 255, 255, 0.65);
  font: 500 12px "Inter", sans-serif;
  cursor: pointer;
}

.logout-btn:hover {
  color: var(--cyan);
  border-color: var(--cyan);
}

.main {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 18px 28px;
  border-bottom: 1px solid var(--line);
}

.topbar-kicker {
  color: var(--blue);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.topbar h2 {
  margin-top: 2px;
  font: 700 22px "Playfair Display", serif;
}

.user-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
}

.user-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--blue);
  color: #FFFFFF;
  font-size: 13px;
  font-weight: 700;
}

.user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

#userEmail {
  font-size: 12px;
  font-weight: 600;
}

.role-badge {
  color: var(--cyan);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.content {
  flex: 1;
  overflow-y: auto;
  padding: 30px;
  background: #F9FBFC;
}

.page-heading {
  margin-bottom: 25px;
}

.eyebrow,
.section-label {
  color: var(--cyan);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.page-heading h1 {
  margin: 8px 0;
  font: 700 30px "Playfair Display", serif;
}

.page-heading p {
  max-width: 650px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.7;
}

.search-panel,
.results-panel {
  margin-bottom: 20px;
  padding: 26px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--card);
}

.panel-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}

.panel-heading h2 {
  margin-top: 6px;
  font: 700 20px "Playfair Display", serif;
}

.timezone-badge {
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--soft);
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field label {
  font-size: 12px;
  font-weight: 700;
}

.field input {
  width: 100%;
  min-height: 44px;
  padding: 11px 13px;
  outline: none;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #FFFFFF;
  color: var(--text);
  font: 500 13px "Inter", sans-serif;
}

.field input:focus {
  border-color: var(--cyan);
  box-shadow: 0 0 0 3px rgba(46, 155, 203, 0.1);
}

.field-help {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin-top: 24px;
}

.form-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 28px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
}

.date-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.secondary-btn,
.primary-btn {
  min-height: 40px;
  padding: 10px 16px;
  border-radius: 8px;
  font: 600 12px "Inter", sans-serif;
  cursor: pointer;
}

.secondary-btn {
  border: 1px solid var(--line);
  background: #FFFFFF;
  color: var(--blue);
}

.secondary-btn:hover {
  background: var(--soft);
}

.primary-btn {
  display: flex;
  align-items: center;
  gap: 18px;
  border: 1px solid var(--blue);
  background: var(--blue);
  color: #FFFFFF;
}

.primary-btn:hover {
  background: var(--ink);
  border-color: var(--ink);
}

.primary-btn:disabled {
  opacity: 0.65;
  cursor: wait;
}

.form-message {
  display: none;
  margin-top: 18px;
  padding: 12px 14px;
  border-radius: 9px;
  font-size: 12px;
  line-height: 1.6;
}

.form-message.show {
  display: block;
}

.form-message.error {
  color: #923939;
  background: #FFF1F1;
  border: 1px solid #EAC2C2;
}

.form-message.success {
  color: var(--blue);
  background: var(--soft);
  border: 1px solid var(--line);
}

/* RESULTADOS */
.results-panel {
  padding: 25px;
}

.results-heading {
  margin-bottom: 18px;
}

.results-count {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 7px 13px;
  border-radius: 999px;
  background: var(--blue);
  color: #FFFFFF;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.results-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 22px;
  padding: 13px 16px;
  margin-bottom: 14px;
  background: #F3F8FB;
  border: 1px solid #E1EFF5;
  border-radius: 10px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.results-summary strong {
  color: var(--ink);
}

.results-summary[hidden],
.results-notice[hidden] {
  display: none;
}

.results-notice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 14px;
  margin-bottom: 20px;
  border: 1px solid #DCECF4;
  border-radius: 10px;
  background: #F5FAFD;
}

.notice-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 18px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--cyan);
  color: #FFFFFF;
  font: 700 11px "Inter", sans-serif;
}

.results-notice p {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.results-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: stretch;
  gap: 16px;
}

.mention-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 255px;
  padding: 19px;
  border: 1px solid #DDE9EF;
  border-radius: 13px;
  background: #FFFFFF;
  box-shadow: 0 3px 14px rgba(47, 50, 59, 0.035);
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}

.mention-card:hover {
  border-color: var(--cyan);
  box-shadow: 0 8px 24px rgba(41, 114, 169, 0.085);
  transform: translateY(-2px);
}

.mention-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-bottom: 15px;
}

.mention-source {
  display: inline-flex;
  align-items: center;
  max-width: 75%;
  padding: 6px 10px;
  border-radius: 6px;
  background: #EAF4FA;
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mention-index {
  flex-shrink: 0;
  color: #8796A0;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
}

.mention-title {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  margin-bottom: 10px;
  min-height: 46px;
  color: var(--ink);
  font: 700 17px/1.38 "Playfair Display", serif;
  overflow-wrap: anywhere;
}

.mention-title-link {
  color: inherit;
  text-decoration: none;
}

.mention-title-link:hover {
  color: var(--blue);
}

.mention-snippet {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  margin: 0 0 16px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.65;
  white-space: normal;
  overflow-wrap: anywhere;
}

.mention-footer {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid #E7EFF3;
}

.mention-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 14px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.6;
}

.mention-meta strong {
  color: var(--ink);
}

.mention-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.verification-badge {
  display: inline-flex;
  align-items: center;
  padding: 6px 8px;
  border: 1px solid #D9E8EF;
  border-radius: 6px;
  background: #F6F9FB;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
}

.mention-link {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 8px 12px;
  border: 1px solid var(--blue);
  border-radius: 7px;
  color: #FFFFFF;
  background: var(--blue);
  font-size: 11px;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.mention-link:hover {
  background: var(--ink);
  border-color: var(--ink);
}

.mention-url {
  overflow: hidden;
  color: #8A97A0;
  font-size: 10px;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 42px 20px;
  text-align: center;
}

.empty-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 18px;
  border-radius: 16px;
  background: var(--soft);
  color: var(--blue);
  font-size: 38px;
}

.empty-state h3 {
  margin-bottom: 9px;
  font: 700 18px "Playfair Display", serif;
}

.empty-state p {
  max-width: 510px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.8;
}

@media (max-width: 1200px) {
  .results-list {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 1000px) {
  .sidebar {
    width: 220px;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
  .panel-heading {
    align-items: flex-start;
    flex-direction: column;
  }
}
@media (max-width: 650px) {
  .sl-app {
    min-width: 0;
  }
  .sidebar {
    width: 160px;
  }
  .brand-row {
    padding: 15px 10px;
  }
  .brand-text {
    display: none;
  }
  .nav-menu {
    padding: 8px;
  }
  .nav-item {
    padding: 9px;
    font-size: 11px;
  }
  .content {
    padding: 16px;
  }
  .topbar {
    padding: 14px;
  }
  .user-chip {
    display: none;
  }
  .search-panel,
  .results-panel {
    padding: 17px;
  }
  .mention-card {
    min-height: 0;
    padding: 16px;
  }
  .mention-actions {
    flex-wrap: wrap;
  }
}

srcDoc.js:
appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');
  function esc(value) {
    var div = document.createElement('div');
    div.textContent = value == null ? '' : String(value);
    return div.innerHTML;
  }
  try {
    var model = appsmith.model || {};
    var role = model.userRole || 'viewer';
    var email = model.userEmail || '';
    var active = model.active || 'tasks';
    document.getElementById('userEmail').textContent = email;
    document.getElementById('userRole').textContent = role.toUpperCase();
    document.getElementById('userAvatar').textContent = email.charAt(0).toUpperCase() || 'A';
    var MENU = [{
      section: 'Análisis',
      items: [{
        id: 'dashboard',
        label: 'Dashboard',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'mentions',
        label: 'Menciones',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'analytics',
        label: 'Analítica',
        roles: ['admin', 'analyst']
      }, {
        id: 'competitors',
        label: 'Competencia',
        roles: ['admin', 'analyst']
      }]
    }, {
      section: 'Gestión',
      items: [{
        id: 'targets',
        label: 'Objetivos',
        roles: ['admin', 'analyst']
      }, {
        id: 'alerts',
        label: 'Alertas',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'reports',
        label: 'Reportes',
        roles: ['admin', 'analyst', 'viewer']
      }]
    }, {
      section: 'Administración',
      items: [{
        id: 'tasks',
        label: 'Tareas de Scrapeo',
        roles: ['admin']
      }, {
        id: 'integrations',
        label: 'Integraciones',
        roles: ['admin']
      }, {
        id: 'users',
        label: 'Usuarios',
        roles: ['admin']
      }, {
        id: 'roles',
        label: 'Roles y Permisos',
        roles: ['admin']
      }, {
        id: 'audit',
        label: 'Auditoría',
        roles: ['admin']
      }, {
        id: 'settings',
        label: 'Configuración',
        roles: ['admin']
      }, {
        id: 'billing',
        label: 'Plan y Suscripción',
        roles: ['admin']
      }]
    }];
    var TITLES = {
      dashboard: 'Dashboard Ejecutivo',
      mentions: 'Menciones',
      analytics: 'Analítica',
      competitors: 'Competencia',
      targets: 'Objetivos Monitoreados',
      alerts: 'Alertas',
      reports: 'Reportes',
      tasks: 'Búsqueda web',
      integrations: 'Integraciones',
      users: 'Usuarios',
      roles: 'Roles y Permisos',
      audit: 'Auditoría',
      settings: 'Configuración',
      billing: 'Plan y Suscripción'
    };
    navMenu.innerHTML = '';
    MENU.forEach(function (section) {
      var visible = section.items.filter(function (item) {
        return item.roles.indexOf(role) !== -1;
      });
      if (!visible.length) {
        return;
      }
      var containsActive = visible.some(function (item) {
        return item.id === active;
      });
      var group = document.createElement('li');
      group.className = 'nav-group' + (containsActive ? '' : ' collapsed');
      var head = document.createElement('div');
      head.className = 'nav-section-head';
      var headLabel = document.createElement('span');
      headLabel.textContent = section.section;
      head.appendChild(headLabel);
      head.addEventListener('click', function () {
        group.classList.toggle('collapsed');
      });
      group.appendChild(head);
      var list = document.createElement('ul');
      list.className = 'nav-group-items';
      visible.forEach(function (item) {
        var li = document.createElement('li');
        li.className = 'nav-item' + (item.id === active ? ' active' : '');
        li.textContent = item.label;
        li.addEventListener('click', function () {
          appsmith.triggerEvent('go_' + item.id);
        });
        list.appendChild(li);
      });
      group.appendChild(list);
      navMenu.appendChild(group);
    });
    document.getElementById('viewTitle').textContent = TITLES[active] || 'Búsqueda web';
    document.getElementById('logoutBtn').addEventListener('click', function () {
      appsmith.triggerEvent('onLogout');
    });
  } catch (error) {
    navMenu.innerHTML = '<li style="color:#A7CDDE;padding:12px;">' + 'Error de navegación: ' + esc(error.message) + '</li>';
    return;
  }
  var phraseInput = document.getElementById('searchPhrase');
  var dateFromInput = document.getElementById('dateFrom');
  var dateToInput = document.getElementById('dateTo');
  var originInput = document.getElementById('originFilter');
  var message = document.getElementById('formMessage');
  var prepareBtn = document.getElementById('prepareBtn');
  var resultsStatus = document.getElementById('resultsStatus');
  var resultsSummary = document.getElementById('resultsSummary');
  var resultsNotice = document.getElementById('resultsNotice');
  var resultsContent = document.getElementById('resultsContent');
  var searchPending = false;
  var lastResponseSignature = null;
  function todayMexico() {
    var parts = new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/Mexico_City',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).formatToParts(new Date());
    var values = {};
    parts.forEach(function (part) {
      values[part.type] = part.value;
    });
    return values.year + '-' + values.month + '-' + values.day;
  }
  function formatDate(value) {
    if (!value) {
      return 'No disponible';
    }
    var text = String(value);
    if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
      var parts = text.split('-');
      return parts[2] + '/' + parts[1] + '/' + parts[0];
    }
    var date = new Date(value);
    if (Number.isNaN(date.getTime())) {
      return 'No disponible';
    }
    return new Intl.DateTimeFormat('es-MX', {
      timeZone: 'America/Mexico_City',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    }).format(date);
  }
  function showMessage(text, type) {
    message.textContent = text;
    message.className = 'form-message show ' + (type || 'success');
  }
  function resetDatesToToday() {
    var today = todayMexico();
    dateFromInput.value = today;
    dateToInput.value = today;
  }
  function setButtonBusy(busy) {
    prepareBtn.disabled = busy;
    if (busy) {
      prepareBtn.textContent = 'Buscando menciones...';
    } else {
      prepareBtn.innerHTML = 'Buscar menciones ' + '<span aria-hidden="true">→</span>';
    }
  }
  function makeElement(tag, className, text) {
    var element = document.createElement(tag);
    if (className) {
      element.className = className;
    }
    if (text !== undefined && text !== null) {
      element.textContent = String(text);
    }
    return element;
  }
  function appendMeta(container, label, value) {
    var item = makeElement('span', '');
