  color: var(--muted);
  font-size: 10px;
  line-height: 1.6;
}

.mention-meta strong {
  color: var(--ink);
}

.mention-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.verification-badge {
  display: inline-flex;
  align-items: center;
  padding: 6px 8px;
  border: 1px solid #D9E8EF;
  border-radius: 6px;
  background: #F6F9FB;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
}

.mention-link {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 8px 12px;
  border: 1px solid var(--blue);
  border-radius: 7px;
  color: #FFFFFF;
  background: var(--blue);
  font-size: 11px;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.mention-link:hover {
  background: var(--ink);
  border-color: var(--ink);
}

.mention-url {
  overflow: hidden;
  color: #8A97A0;
  font-size: 10px;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 42px 20px;
  text-align: center;
}

.empty-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 18px;
  border-radius: 16px;
  background: var(--soft);
  color: var(--blue);
  font-size: 38px;
}

.empty-state h3 {
  margin-bottom: 9px;
  font: 700 18px 'Playfair Display', serif;
}

.empty-state p {
  max-width: 510px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.8;
}

@media (max-width: 1200px) {
  .results-list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1000px) {
  .sidebar {
    width: 220px;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .panel-heading {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 650px) {
  .sl-app {
    min-width: 0;
  }

  .sidebar {
    width: 160px;
  }

  .brand-row {
    padding: 15px 10px;
  }

  .brand-text {
    display: none;
  }

  .nav-menu {
    padding: 8px;
  }

  .nav-item {
    padding: 9px;
    font-size: 11px;
  }

  .content {
    padding: 16px;
  }

  .topbar {
    padding: 14px;
  }

  .user-chip {
    display: none;
  }

  .search-panel,
  .results-panel {
    padding: 17px;
  }

  .mention-card {
    min-height: 0;
    padding: 16px;
  }

  .mention-actions {
    flex-wrap: wrap;
  }
}

