appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');

  function esc(value) {
    var div = document.createElement('div');
    div.textContent = value == null ? '' : String(value);
    return div.innerHTML;
  }

  try {
    var model = appsmith.model || {};
    var role = model.userRole || 'viewer';
    var email = model.userEmail || '';
    var active = model.active || 'tasks';

    document.getElementById('userEmail').textContent = email;

    document.getElementById('userRole').textContent =
      role.toUpperCase();

    document.getElementById('userAvatar').textContent =
      email.charAt(0).toUpperCase() || 'A';

    var MENU = [
      {
        section: 'Análisis',
        items: [
          {
            id: 'dashboard',
            label: 'Dashboard',
            roles: ['admin', 'analyst', 'viewer']
          },
          {
            id: 'mentions',
            label: 'Menciones',
            roles: ['admin', 'analyst', 'viewer']
          },
          {
            id: 'analytics',
            label: 'Analítica',
            roles: ['admin', 'analyst']
          },
          {
            id: 'competitors',
            label: 'Competencia',
            roles: ['admin', 'analyst']
          }
        ]
      },
      {
        section: 'Gestión',
        items: [
          {
            id: 'targets',
            label: 'Objetivos',
            roles: ['admin', 'analyst']
          },
          {
            id: 'alerts',
            label: 'Alertas',
            roles: ['admin', 'analyst', 'viewer']
          },
          {
            id: 'reports',
            label: 'Reportes',
            roles: ['admin', 'analyst', 'viewer']
          }
        ]
      },
      {
        section: 'Administración',
        items: [
          {
            id: 'tasks',
            label: 'Tareas de Scrapeo',
            roles: ['admin']
          },
          {
            id: 'integrations',
            label: 'Integraciones',
            roles: ['admin']
          },
          {
            id: 'users',
            label: 'Usuarios',
            roles: ['admin']
          },
          {
            id: 'roles',
            label: 'Roles y Permisos',
            roles: ['admin']
          },
          {
            id: 'audit',
            label: 'Auditoría',
            roles: ['admin']
          },
          {
            id: 'settings',
            label: 'Configuración',
            roles: ['admin']
          },
          {
            id: 'billing',
            label: 'Plan y Suscripción',
            roles: ['admin']
          }
        ]
      }
    ];

    var TITLES = {
      dashboard: 'Dashboard Ejecutivo',
      mentions: 'Menciones',
      analytics: 'Analítica',
      competitors: 'Competencia',
      targets: 'Objetivos Monitoreados',
      alerts: 'Alertas',
      reports: 'Reportes',
      tasks: 'Búsqueda web',
      integrations: 'Integraciones',
      users: 'Usuarios',
      roles: 'Roles y Permisos',
      audit: 'Auditoría',
      settings: 'Configuración',
      billing: 'Plan y Suscripción'
    };

    navMenu.innerHTML = '';

    MENU.forEach(function (section) {
      var visible = section.items.filter(function (item) {
        return item.roles.indexOf(role) !== -1;
      });

      if (!visible.length) {
        return;
      }

      var containsActive = visible.some(function (item) {
        return item.id === active;
      });

      var group = document.createElement('li');

      group.className =
        'nav-group' + (containsActive ? '' : ' collapsed');

      var head = document.createElement('div');
      head.className = 'nav-section-head';

      var headLabel = document.createElement('span');
      headLabel.textContent = section.section;

      head.appendChild(headLabel);

      head.addEventListener('click', function () {
        group.classList.toggle('collapsed');
      });

      group.appendChild(head);

      var list = document.createElement('ul');
      list.className = 'nav-group-items';

      visible.forEach(function (item) {
        var li = document.createElement('li');

        li.className =
          'nav-item' + (item.id === active ? ' active' : '');

        li.textContent = item.label;

        li.addEventListener('click', function () {
          appsmith.triggerEvent('go_' + item.id);
        });

        list.appendChild(li);
      });

      group.appendChild(list);
      navMenu.appendChild(group);
    });

    document.getElementById('viewTitle').textContent =
      TITLES[active] || 'Búsqueda web';

    document.getElementById('logoutBtn')
      .addEventListener('click', function () {
        appsmith.triggerEvent('onLogout');
      });

  } catch (error) {
    navMenu.innerHTML =
      '<li style="color:#A7CDDE;padding:12px;">' +
      'Error de navegación: ' +
      esc(error.message) +
      '</li>';

    return;
  }

  var phraseInput = document.getElementById('searchPhrase');
  var dateFromInput = document.getElementById('dateFrom');
  var dateToInput = document.getElementById('dateTo');
  var originInput = document.getElementById('originFilter');
  var message = document.getElementById('formMessage');
  var prepareBtn = document.getElementById('prepareBtn');

  var resultsStatus = document.getElementById('resultsStatus');
  var resultsSummary = document.getElementById('resultsSummary');
  var resultsNotice = document.getElementById('resultsNotice');
  var resultsContent = document.getElementById('resultsContent');

  var searchPending = false;
  var lastResponseSignature = null;

  function todayMexico() {
    var parts = new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/Mexico_City',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).formatToParts(new Date());

    var values = {};

    parts.forEach(function (part) {
      values[part.type] = part.value;
    });

    return (
      values.year + '-' +
      values.month + '-' +
      values.day
    );
  }

  function formatDate(value) {
    if (!value) {
      return 'No disponible';
    }

    var text = String(value);

    if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
      var parts = text.split('-');

      return (
        parts[2] + '/' +
        parts[1] + '/' +
        parts[0]
      );
    }

    var date = new Date(value);

    if (Number.isNaN(date.getTime())) {
      return 'No disponible';
    }

    return new Intl.DateTimeFormat('es-MX', {
      timeZone: 'America/Mexico_City',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    }).format(date);
  }

  function showMessage(text, type) {
    message.textContent = text;

    message.className =
      'form-message show ' + (type || 'success');
  }

  function resetDatesToToday() {
    var today = todayMexico();

    dateFromInput.value = today;
    dateToInput.value = today;
  }

  function setButtonBusy(busy) {
    prepareBtn.disabled = busy;

    if (busy) {
      prepareBtn.textContent = 'Buscando menciones...';
    } else {
      prepareBtn.innerHTML =
        'Buscar menciones ' +
        '<span aria-hidden="true">→</span>';
    }
  }

  function makeElement(tag, className, text) {
    var element = document.createElement(tag);

    if (className) {
      element.className = className;
    }

    if (text !== undefined && text !== null) {
      element.textContent = String(text);
    }

    return element;
  }

  function appendMeta(container, label, value) {
    var item = makeElement('span', '');

    item.appendChild(
      makeElement('strong', '', label + ': ')
    );

    item.appendChild(
      document.createTextNode(String(value))
    );

    container.appendChild(item);
  }

  function showEmptyState(title, description) {
    resultsContent.replaceChildren();

    var state = makeElement('div', 'empty-state');

    state.appendChild(
      makeElement('div', 'empty-icon', '⌕')
    );

    state.appendChild(
      makeElement('h3', '', title)
    );

    state.appendChild(
      makeElement('p', '', description)
    );

    resultsContent.appendChild(state);
  }

  /*
   * Limpia exclusivamente el extracto visual.
   * No modifica el texto almacenado ni la respuesta de Tavily.
   */
  function cleanSnippet(value, phrase) {
    var raw = String(value || '');

    if (!raw.trim()) {
      return 'Sin extracto disponible.';
    }

    raw = raw
      .replace(/\r/g, '\n')
      .replace(/\[\.\.\.\]/g, ' ')
      .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
      .replace(/https?:\/\/\S+/g, ' ')
      .replace(/^\s*#{1,6}\s*/gm, '')
      .replace(/[ \t]+/g, ' ');

    var lines = raw
      .split(/\n+/)
      .map(function (line) {
        return line.trim();
      })
      .filter(function (line) {
        if (line.length < 25) {
          return false;
        }

        if (/^(log in|log out|forgot account|sign up|síguenos|follow|see more|mostrar más|all reactions|privacy|terms|ad choices|cookies|like|comment|share)$/i.test(line)) {
          return false;
        }

        if (/^(image|video|foto)\s+\d+(?:\s*\+\d+)?\s*$/i.test(line)) {
          return false;
        }

        if (/^\d+\s+(comments|shares|reactions|comentarios|veces compartido)$/i.test(line)) {
          return false;
        }

        if (/^[\[\]()#\s]+$/.test(line)) {
          return false;
        }

        return true;
      });

    if (!lines.length) {
      return 'Extracto no disponible. Abre la fuente para consultar el contenido.';
    }

    var key = String(phrase || '')
      .trim()
      .toLocaleLowerCase('es');

    var matching = key
      ? lines.filter(function (line) {
          return line.toLocaleLowerCase('es').includes(key);
        })
      : [];

    var chosen =
      matching.find(function (line) {
        return line.length >= 75 && line.length <= 650;
      }) ||
      matching.find(function (line) {
        return line.length >= 35;
      }) ||
      lines.find(function (line) {
        return line.length >= 60;
      }) ||
      lines[0];

    chosen = chosen
      .replace(/\s+/g, ' ')
      .replace(/\s*\[\s*\]\s*/g, ' ')
      .trim();

    if (chosen.length <= 260) {
      return chosen;
    }

    var position = key
      ? chosen.toLocaleLowerCase('es').indexOf(key)
      : -1;

    var start = position > 65
      ? position - 45
      : 0;

    var excerpt = chosen
      .slice(start, start + 260)
      .trim();

    if (start > 0) {
      excerpt = '… ' + excerpt;
    }

    if (start + 260 < chosen.length) {
      excerpt += '…';
    }

    return excerpt;
  }

  function showLoading() {
    resultsStatus.textContent = 'Consultando';

    resultsSummary.hidden = true;
    resultsNotice.hidden = true;

    resultsContent.setAttribute('aria-busy', 'true');

    showEmptyState(
      'Consultando fuentes web',
      'La consulta está en proceso. Espera la respuesta del motor de búsqueda.'
    );
  }

  function normalizeResponse(raw) {
    var data = raw;

    if (typeof data === 'string') {
      try {
        data = JSON.parse(data);
      } catch (error) {
        throw new Error(
          'La API devolvió texto que no es JSON válido.'
        );
      }
    }

    if (Array.isArray(data)) {
      data = data[0] || null;
    }

    if (!data || typeof data !== 'object') {
      return null;
    }

    if (!Array.isArray(data.results)) {
      throw new Error(
        'La respuesta de la API no contiene un array results.'
      );
    }

    return data;
  }

  function renderMention(item, index, total, phrase) {
    var card = makeElement('article', 'mention-card');

    var sourceUrl = String(item.source_url || '').trim();

    var validUrl =
      /^https?:\/\/[^\s]+$/i.test(sourceUrl);

    var source = String(
      item.source_domain ||
      item.source_name ||
      'Origen no identificado'
    );

    var top = makeElement('div', 'mention-top');

    top.appendChild(
      makeElement('span', 'mention-source', source)
    );

    top.appendChild(
      makeElement(
        'span',
        'mention-index',
        String(index + 1).padStart(2, '0') +
        ' / ' +
        String(total).padStart(2, '0')
      )
    );

    card.appendChild(top);

    var title = makeElement('h3', 'mention-title');

    if (validUrl) {
      var titleLink = makeElement(
        'a',
        'mention-title-link',
        item.title || 'Resultado sin título'
      );

      titleLink.href = sourceUrl;
      titleLink.target = '_blank';
      titleLink.rel = 'noopener noreferrer';

      title.appendChild(titleLink);
    } else {
      title.textContent =
        item.title || 'Resultado sin título';
    }

    card.appendChild(title);

    card.appendChild(
      makeElement(
        'p',
        'mention-snippet',
        cleanSnippet(item.snippet, phrase)
      )
    );

    var footer = makeElement('div', 'mention-footer');

    var meta = makeElement('div', 'mention-meta');

    appendMeta(
      meta,
      'Fecha atribuida',
      item.date_mexico
        ? formatDate(item.date_mexico)
        : 'No disponible'
    );

    appendMeta(
      meta,
      'Detectado',
      formatDate(item.detected_at)
    );

    footer.appendChild(meta);

    var actions = makeElement('div', 'mention-actions');

    actions.appendChild(
      makeElement(
        'span',
        'verification-badge',
        item.date_verified === true
          ? 'Fecha indicada como verificada'
          : 'Fecha sin verificar'
      )
    );

    if (validUrl) {
      var link = makeElement(
        'a',
        'mention-link',
        'Abrir fuente ↗'
      );

      link.href = sourceUrl;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';

      actions.appendChild(link);
    }

    footer.appendChild(actions);

    if (validUrl) {
      var url = makeElement(
        'p',
        'mention-url',
        sourceUrl
      );

      url.title = sourceUrl;

      footer.appendChild(url);
    }

    card.appendChild(footer);

    return card;
  }

  function renderResponse(raw) {
    var data;

    try {
      data = normalizeResponse(raw);
    } catch (error) {
      searchPending = false;
      setButtonBusy(false);

      resultsStatus.textContent = 'Error';

      resultsContent.setAttribute('aria-busy', 'false');

      resultsSummary.hidden = true;
      resultsNotice.hidden = true;

      showEmptyState(
        'Respuesta no reconocida',
        error.message
      );

      showMessage(error.message, 'error');

      return;
    }

    if (!data) {
      return;
    }

    searchPending = false;
    setButtonBusy(false);

    resultsContent.setAttribute('aria-busy', 'false');

    var results = data.results;

    var totalReceived =
      Number.isFinite(Number(data.total_received))
        ? Number(data.total_received)
        : results.length;

    var totalFiltered =
      Number.isFinite(Number(data.total_filtered))
        ? Number(data.total_filtered)
        : results.length;

    resultsStatus.textContent =
      totalFiltered + ' resultados';

    resultsSummary.replaceChildren();

    var summaryItems = [
      ['Consulta', data.query || 'No disponible'],
      [
        'Período',
        formatDate(data.dateFrom) +
        ' — ' +
        formatDate(data.dateTo)
      ],
      ['Recuperados', totalReceived],
      ['Filtrados', totalFiltered],
      [
        'Origen',
        data.originFilter || 'Todos los sitios'
      ]
    ];

    summaryItems.forEach(function (entry) {
      var item = makeElement('span', '');

      item.appendChild(
        makeElement('strong', '', entry[0] + ': ')
      );

      item.appendChild(
        document.createTextNode(String(entry[1]))
      );

      resultsSummary.appendChild(item);
    });

    resultsSummary.hidden = false;
    resultsNotice.hidden = false;

    resultsContent.replaceChildren();

    if (results.length === 0) {
      showEmptyState(
        'No se encontraron coincidencias',
        'El buscador no recuperó resultados que cumplieran los filtros. Esto no demuestra que no existan publicaciones.'
      );

      showMessage(
        'Búsqueda finalizada sin coincidencias recuperadas.',
        'success'
      );

      return;
    }

    var list = makeElement('div', 'results-list');

    results.forEach(function (item, index) {
      list.appendChild(
        renderMention(
          item,
          index,
          results.length,
          data.query || ''
        )
      );
    });

    resultsContent.appendChild(list);

    showMessage(
      'Búsqueda finalizada. Se muestran ' +
      results.length +
      ' resultados con sus fuentes.',
      'success'
    );
  }

  function signatureOf(value) {
    try {
      return JSON.stringify(value);
    } catch (error) {
      return null;
    }
  }

  function processModel(model) {
    var raw = model ? model.searchResponse : null;

    if (
      raw === null ||
      raw === undefined ||
      raw === ''
    ) {
      return;
    }

    var signature = signatureOf(raw);

    if (
      signature !== null &&
      signature === lastResponseSignature
    ) {
      return;
    }

    lastResponseSignature = signature;

    renderResponse(raw);
  }

  var initialModel = appsmith.model || {};

  phraseInput.value =
    initialModel.searchPhrase || '';

  dateFromInput.value =
    initialModel.dateFrom || todayMexico();

  dateToInput.value =
    initialModel.dateTo || todayMexico();

  originInput.value =
    initialModel.originFilter || '';

  document.getElementById('todayBtn')
    .addEventListener('click', function () {
      resetDatesToToday();
      message.className = 'form-message';
    });

  document.getElementById('clearOriginBtn')
    .addEventListener('click', function () {
      originInput.value = '';
      message.className = 'form-message';
    });

  document.getElementById('webSearchForm')
    .addEventListener('submit', function (event) {
      event.preventDefault();

      if (searchPending) {
        return;
      }

      var phrase = phraseInput.value.trim();
      var dateFrom = dateFromInput.value;
      var dateTo = dateToInput.value;
      var origin = originInput.value.trim();

      if (!phrase) {
        showMessage(
          'Introduce una palabra o frase para realizar la búsqueda.',
          'error'
        );

        phraseInput.focus();
        return;
      }

      if (!dateFrom || !dateTo) {
        showMessage(
          'Selecciona las fechas inicial y final.',
          'error'
        );

        return;
      }

      if (dateFrom > dateTo) {
        showMessage(
          'La fecha inicial no puede ser posterior a la fecha final.',
          'error'
        );

        return;
      }

      var searchParams = {
        searchPhrase: phrase,
        dateFrom: dateFrom,
        dateTo: dateTo,
        originFilter: origin,
        searchTimeZone: 'America/Mexico_City'
      };

      lastResponseSignature = signatureOf(
        (appsmith.model || {}).searchResponse
      );

      searchPending = true;

      setButtonBusy(true);
      showLoading();

      showMessage(
        'Consulta enviada al motor de búsqueda.',
        'success'
      );

      appsmith.updateModel(searchParams);

      appsmith.triggerEvent('onSearch');
    });

  appsmith.onModelChange(function (newModel) {
    processModel(newModel);
  });

  processModel(initialModel);
});
